function coinRoundTrip(coins: number[], edges: number[][]): number {
  const n = coins.length;
  const adj: number[][] = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
  let best = Infinity;
  for (let root = 0; root < n; root++) {
    const parent = new Array(n).fill(-2);
    parent[root] = -1;
    const order = [root];
    for (let i = 0; i < order.length; i++) {
      for (const v of adj[order[i]]) if (parent[v] === -2) { parent[v] = order[i]; order.push(v); }
    }
    const mark = new Array(n).fill(false);
    let count = 0;
    for (let c = 0; c < n; c++) {
      if (!coins[c]) continue;
      let a = c;
      for (let s = 0; s < 2 && a !== root; s++) a = parent[a];
      while (a !== -1 && !mark[a]) { mark[a] = true; count++; a = parent[a]; }
    }
    best = Math.min(best, 2 * Math.max(0, count - 1));
  }
  return best;
}

