function coinRoundTrip(coins: number[], edges: number[][]): number {
  const n = coins.length;
  const adj: number[][] = Array.from({ length: n }, () => []);
  const deg = new Array(n).fill(0);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); deg[a]++; deg[b]++; }
  const removed = new Array(n).fill(false);
  let left = n;
  const remove = (u: number) => {
    removed[u] = true;
    left--;
    for (const v of adj[u]) if (!removed[v]) deg[v]--;
  };
  const queue: number[] = [];
  for (let u = 0; u < n; u++) if (deg[u] === 1 && !coins[u]) queue.push(u);
  for (let i = 0; i < queue.length; i++) {
    const u = queue[i];
    remove(u);
    for (const v of adj[u]) if (!removed[v] && deg[v] === 1 && !coins[v]) queue.push(v);
  }
  for (let round = 0; round < 2; round++) {
    const leaves: number[] = [];
    for (let u = 0; u < n; u++) if (!removed[u] && deg[u] === 1) leaves.push(u);
    for (const u of leaves) if (!removed[u]) remove(u);
  }
  return left > 0 ? 2 * (left - 1) : 0;
}

