class Solution:
    def coinRoundTrip(self, coins: List[int], edges: List[List[int]]) -> int:
        n = len(coins)
        adj = [[] for _ in range(n)]
        deg = [0] * n
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
            deg[a] += 1
            deg[b] += 1
        removed = [False] * n
        left = n

        def remove(u):
            nonlocal left
            removed[u] = True
            left -= 1
            for v in adj[u]:
                if not removed[v]:
                    deg[v] -= 1

        queue = deque(u for u in range(n) if deg[u] == 1 and not coins[u])
        while queue:
            u = queue.popleft()
            remove(u)
            for v in adj[u]:
                if not removed[v] and deg[v] == 1 and not coins[v]:
                    queue.append(v)
        for _ in range(2):
            leaves = [u for u in range(n) if not removed[u] and deg[u] == 1]
            for u in leaves:
                if not removed[u]:
                    remove(u)
        return 2 * (left - 1) if left > 0 else 0

